from datetime import datetime, timezone
from decimal import Decimal
from ledgerly import audit
from ledgerly.adjustments import refund_shipping
from ledgerly.errors import BillingError
from ledgerly.models import Payment

T0 = datetime(2026,1,1,tzinfo=timezone.utc)
def mk(amt="100.00"):
    return Payment("p","i",Decimal(amt),status="captured",created_at=T0,captured_at=T0)

# partial then full
p=mk(); refund_shipping(p,Decimal("40.00"),T0); assert p.refunded_amount==Decimal("40.00") and p.status=="captured"
refund_shipping(p,Decimal("60.00"),T0); assert p.refunded_amount==Decimal("100.00") and p.status=="refunded"
print("partial/full ok", audit.events("shipping_refunded"))

# over refund
p=mk()
try: refund_shipping(p,Decimal("100.01"),T0); print("FAIL")
except BillingError as e: print("over:",e.code)

# non-positive
for a in ("0","-1"):
    try: refund_shipping(mk(),Decimal(a),T0); print("FAIL")
    except BillingError as e: print("nonpos:",e.code)

# approval threshold
p=mk("1000.00")
try: refund_shipping(p,Decimal("500.01"),T0); print("FAIL")
except BillingError as e: print("approval:",e.code)
refund_shipping(p,Decimal("500.00"),T0); print("at threshold ok")
refund_shipping(p,Decimal("500.01"),T0,approved_by="mgr"); print("approved ok")

# idempotency
audit.clear(); p=mk()
refund_shipping(p,Decimal("10.00"),T0,idempotency_key="k1")
refund_shipping(p,Decimal("10.00"),T0,idempotency_key="k1")
assert p.refunded_amount==Decimal("10.00")
print("idempotent ok, events:",len(audit.events("shipping_refunded")))

# non-captured
try: refund_shipping(Payment("p","i",Decimal("10"),status="authorized"),Decimal("1"),T0); print("FAIL")
